class MessageFlowAliasStore(object):

    _ALIAS_STORE = {}

    _instance = None

    def __new__(cls, *args, **kwargs):
        if not cls._instance:
            cls._instance = super(MessageFlowAliasStore, cls).__new__(cls, *args, **kwargs)
        return cls._instance

    def add_flow_alias(self, flow_alias, message_type, **kwargs):
        self._ALIAS_STORE[flow_alias] = (message_type, kwargs)

    def get_flow_alias_by_name(self, flow_alias):
        return self._ALIAS_STORE[flow_alias]
